import{_ as a,o,c,a2 as d}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Realtime advanced III testing — v0.3 8 axis SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/realtime-advanced-III-testing.md","filePath":"concepts/realtime-advanced-III-testing.md"}'),i={name:"concepts/realtime-advanced-III-testing.md"};function r(t,e,s,n,l,p){return o(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="realtime-advanced-iii-testing-—-v0-3-8-axis-ssot" tabindex="-1">Realtime advanced III testing — v0.3 8 axis SSOT <a class="header-anchor" href="#realtime-advanced-iii-testing-—-v0-3-8-axis-ssot" aria-label="Permalink to &quot;Realtime advanced III testing — v0.3 8 axis SSOT&quot;">​</a></h1><h2 id="what-this-covers" tabindex="-1">What this covers <a class="header-anchor" href="#what-this-covers" aria-label="Permalink to &quot;What this covers&quot;">​</a></h2><p><code>@kiwa-lab/realtime</code> v0.3 layers 8 advanced III axes on top of the v0.2 base (WebRTC + WebTransport + HTTP/3 + QUIC 8 axis)。 v0.3 introduces 3 new protocols (MoQ / WebCodecs / AI-media) and 8 axes for Media over QUIC delivery + WebCodecs direct API + LLM voice / Whisper ASR / realtime AI inference。</p><h2 id="pair-第-2-pair-3-段拡張達成-3-例目-record" tabindex="-1">Pair 第 2 pair 3 段拡張達成 (3 例目 record) <a class="header-anchor" href="#pair-第-2-pair-3-段拡張達成-3-例目-record" aria-label="Permalink to &quot;Pair 第 2 pair 3 段拡張達成 (3 例目 record)&quot;">​</a></h2><p>v1.45 achieves the <strong>2nd 縦深化 pair 3 段拡張</strong> (Realtime base → v1.28 II → v1.45 III)。 pair 第 8 Search (v1.36) + pair 第 1 Auth (v1.44) に続く <strong>3 例目 pair 深度 3 段記録</strong>、 3 段拡張 pattern の 3 例安定化を実証。</p><h2 id="the-8-v0-3-advanced-iii-axes" tabindex="-1">The 8 v0.3 advanced III axes <a class="header-anchor" href="#the-8-v0-3-advanced-iii-axes" aria-label="Permalink to &quot;The 8 v0.3 advanced III axes&quot;">​</a></h2><h3 id="moq-fetch-axis" tabindex="-1">moq-fetch axis <a class="header-anchor" href="#moq-fetch-axis" aria-label="Permalink to &quot;moq-fetch axis&quot;">​</a></h3><p><code>createMoqFetchMock()</code> + <code>announceTrack</code> + <code>subscribeTrack</code> + <code>sendObject</code> + <code>receiveObject</code>。 MoQT (draft-ietf-moq-transport) 仕様の pub/sub media transport pattern。</p><h3 id="moq-datagram-media-axis" tabindex="-1">moq-datagram-media axis <a class="header-anchor" href="#moq-datagram-media-axis" aria-label="Permalink to &quot;moq-datagram-media axis&quot;">​</a></h3><p><code>createMoqDatagramMediaMock()</code> + <code>sendDatagram</code> + <code>dropDatagram</code> + <code>setPriority</code> + <code>recoverFec</code>。 partial reliability + Forward Error Correction pattern。</p><h3 id="webcodecs-encoder-axis" tabindex="-1">webcodecs-encoder axis <a class="header-anchor" href="#webcodecs-encoder-axis" aria-label="Permalink to &quot;webcodecs-encoder axis&quot;">​</a></h3><p><code>createWebCodecsEncoderMock()</code> + <code>configure</code> + <code>encodeFrame</code> + <code>forceKeyframe</code> + <code>reportHardwareUsed</code>。 VideoEncoder / AudioEncoder direct API + hardware acceleration hints。</p><h3 id="webcodecs-decoder-axis" tabindex="-1">webcodecs-decoder axis <a class="header-anchor" href="#webcodecs-decoder-axis" aria-label="Permalink to &quot;webcodecs-decoder axis&quot;">​</a></h3><p><code>createWebCodecsDecoderMock()</code> + <code>configure</code> + <code>decodeFrame</code> + <code>reorderFrame</code> + <code>dropFrame</code>。 VideoDecoder / AudioDecoder + reorder buffer + drop policy。</p><h3 id="simulcast-svc-axis" tabindex="-1">simulcast-svc axis <a class="header-anchor" href="#simulcast-svc-axis" aria-label="Permalink to &quot;simulcast-svc axis&quot;">​</a></h3><p><code>createSimulcastSvcMock()</code> + <code>addSimulcastLayer</code> + <code>selectSvcLayer</code> + <code>adaptBitrate</code> + <code>dropLayer</code>。 Simulcast + Scalable Video Coding (L1T1 → L3T3) + adaptive bitrate。</p><h3 id="voice-streaming-axis" tabindex="-1">voice-streaming axis <a class="header-anchor" href="#voice-streaming-axis" aria-label="Permalink to &quot;voice-streaming axis&quot;">​</a></h3><p><code>createVoiceStreamingMock()</code> + <code>openSession</code> + <code>sendAudioChunk</code> + <code>receiveResponseChunk</code> + <code>completeTurn</code>。 OpenAI Realtime API + Anthropic voice pattern。</p><h3 id="whisper-streaming-axis" tabindex="-1">whisper-streaming axis <a class="header-anchor" href="#whisper-streaming-axis" aria-label="Permalink to &quot;whisper-streaming axis&quot;">​</a></h3><p><code>createWhisperStreamingMock()</code> + <code>sendAudioChunk</code> + <code>emitPartialTranscript</code> + <code>emitFinalTranscript</code> + <code>triggerVad</code>。 Whisper streaming ASR + partial transcript + Voice Activity Detection。</p><h3 id="realtime-ai-inference-axis" tabindex="-1">realtime-ai-inference axis <a class="header-anchor" href="#realtime-ai-inference-axis" aria-label="Permalink to &quot;realtime-ai-inference axis&quot;">​</a></h3><p><code>createRealtimeAiInferenceMock()</code> + <code>sendRequest</code> + <code>receiveResponse</code> + <code>reportBudget</code> + <code>dropRequest</code>。 per-frame prediction + latency budget enforcement + drop policy。</p><h2 id="_6-protocol-×-8-axis-fidelity-grid" tabindex="-1">6-protocol × 8-axis fidelity grid <a class="header-anchor" href="#_6-protocol-×-8-axis-fidelity-grid" aria-label="Permalink to &quot;6-protocol × 8-axis fidelity grid&quot;">​</a></h2><p>Realtime v0.3 は v0.2 + v0.3 合計 16 axis を 6 protocol (webrtc / webtransport / http3-quic / moqt / webcodecs / ai-media) に分割、 4 provider (Supabase / Ably / Pusher / Socket.io) × 16 axis = 64 cell の provider grid + 6 protocol grouping。</p><h2 id="dogfood-app-real-driver-env-gate" tabindex="-1">Dogfood app real-driver env-gate <a class="header-anchor" href="#dogfood-app-real-driver-env-gate" aria-label="Permalink to &quot;Dogfood app real-driver env-gate&quot;">​</a></h2><p>3 dogfood apps ship in v1.45。</p><ul><li><code>dogfood-realtime-moq-webcodecs-app</code> — moq + webcodecs-encoder + simulcast-svc。 <code>KIWA_MODE=real</code> + <code>REALTIME_MEDIA_STACK_READY=1</code> + <code>KIWA_REALTIME_MEDIA_URL</code>。</li><li><code>dogfood-realtime-voice-streaming-app</code> — voice + whisper + ai-inference。 <code>KIWA_MODE=real</code> + <code>REALTIME_AI_STACK_READY=1</code> + <code>KIWA_REALTIME_AI_URL</code>。</li><li><code>dogfood-realtime-svc-adaptive-app</code> — svc + decoder + moq-datagram。 <code>KIWA_MODE=real</code> + <code>REALTIME_ADAPTIVE_STACK_READY=1</code> + <code>KIWA_REALTIME_ADAPTIVE_URL</code>。</li></ul><h2 id="related-concepts" tabindex="-1">Related concepts <a class="header-anchor" href="#related-concepts" aria-label="Permalink to &quot;Related concepts&quot;">​</a></h2><ul><li><code>webrtc-webtransport-testing.md</code> (v1.28 pair 2 base 深化 II の 8 axis)</li><li><code>realtime-testing.md</code> (v1.13 realtime v0.1 5 base semantics)</li><li><code>auth-advanced-III-testing.md</code> (v1.44 pair 1 depth-3 achievement)</li><li><code>edge-serverless-advanced-testing.md</code> (v1.43 pair 12 new base pair)</li></ul>',29)])])}const v=a(i,[["render",r]]);export{m as __pageData,v as default};
